import java.util.*;

public class Graph {
    private Map<String, List<Edge>> graph;

    public Graph() {
        this.graph = new HashMap<>();
    }

    public void addEdge(String source, String destination) {
        if (!graph.containsKey(source)) {
            graph.put(source, new ArrayList<>());
        }
        graph.get(source).add(new Edge(destination, 1));
    }

    public int getDegree(String node) {
        return graph.getOrDefault(node, Collections.emptyList()).size();
    }

    public void printGraph() {
        for (Map.Entry<String, List<Edge>> entry : graph.entrySet()) {
            System.out.println(entry.getKey() + " -> " + entry.getValue());
        }
    }
}

class Edge {
    private String destination;
    private int weight;

    public Edge(String destination, int weight) {
        this.destination = destination;
        this.weight = weight;
    }

    @Override
    public boolean equals(Object o) {
        if (this == o) return true;
        if (o == null || getClass() != o.getClass()) return false;
        Edge edge = (Edge) o;
        return weight == edge.weight && Objects.equals(destination, edge.destination);
    }

    @Override
    public int hashCode() {
        return Objects.hash(destination, weight);
    }
}

class Main {

    public static void main(String[] args) {
        Graph graph = new Graph();

        // Add edges to the graph
        graph.addEdge("A", "B");
        graph.addEdge("A", "C");
        graph.addEdge("B", "D");

        System.out.println("Degree of A: " + graph.getDegree("A"));
        System.out.println("Degree of B: " + graph.getDegree("B"));
        System.out.println("Degree of C: " + graph.getDegree("C"));
        System.out.println("Degree of D: " + graph.getDegree("D"));

        // Print the graph
        graph.printGraph();
    }
